"""Generate reviewable requirement traceability from the runtime catalog."""
import argparse
import json
from pathlib import Path


def traceability(root):
    rows = json.loads((root / "nova/feature_catalog.json").read_text(encoding="utf-8"))
    lines = ["# Advanced expansion requirement traceability", "",
             "Generated by `python scripts/sync_roadmap.py` from `nova/feature_catalog.json`.", "",
             "The [Omega 12 master specification](NOVA_MASTER_SPEC.md) is canonical. These 132 records remain historical references. "
             "The [full expansion prompt](spec/NOVA_ADVANCED_EXPANSION.md) preserves every requirement. "
             "Evidence paths are references, not a claim that tests ran on this machine or that external services are connected.", "",
             "WORKING is limited to each stated scope. PARTIAL never means the entire feature works. "
             "Sections 129–132 are documentation guidance, excluded from runtime feature counts.", "",
             "| ID | Requirement | Status | Implemented scope / limits | Implementation | Test references | Release |",
             "| --- | --- | --- | --- | --- | --- | --- |"]
    def cell(value):
        return str(value).replace("|", "\\|").replace("\n", " ")
    for r in rows:
        lines.append("| " + " | ".join(cell(v) for v in (r['id'], r['title'], r['status'], r['scope'],
                     ", ".join(r['implementation']) or "—", ", ".join(r['tests']) or "—", r['release'] or "Future")) + " |")
    return "\n".join(lines) + "\n"


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    root = Path(__file__).resolve().parent.parent
    for filename, content in (('EXPANSION_TRACEABILITY.md', traceability(root)), ('REQUIREMENT_MATRIX.md', master_traceability(root))):
        target = root / 'docs' / filename
        if args.check:
            if not target.exists() or target.read_text(encoding="utf-8") != content:
                raise SystemExit("Traceability is stale. Run python scripts/sync_roadmap.py.")
        else:
            target.write_text(content, encoding="utf-8")
    print('Requirement matrices match the catalogs.' if args.check else 'Updated expansion and Omega 12 requirement matrices.')


def master_traceability(root):
    rows = json.loads((root / 'nova/omega_requirements.json').read_text(encoding='utf-8'))
    lines = ['# NOVA Omega 12 requirement matrix', '',
             'Canonical source: [NOVA_MASTER_SPEC.md](NOVA_MASTER_SPEC.md). Runtime release: **0.4.0**, not a completed Omega product.', '',
             'Generated from `nova/omega_requirements.json` by `python scripts/sync_roadmap.py`. Status is scoped implementation evidence, not provider/hardware availability. Windows API tests are mocked; local uploaded-image OCR is implemented; live cloud/Windows validation, voice and device mesh remain outstanding. Earlier [v8 coverage](REQUIREMENTS_STATUS.md) and [132 expansion requirements](EXPANSION_TRACEABILITY.md) remain preserved.', '',
             '| Requirement | Subsystem | Status | Scope | Implementation | Tests | Blocker | Version |',
             '| --- | --- | --- | --- | --- | --- | --- | --- |']
    for row in rows:
        values = [row['id'], row['title'], row['status'], row['scope'], ', '.join(row['implementation']) or '—', ', '.join(row['tests']) or '—', row['blocker'], row['release'] or 'Future']
        lines.append('| ' + ' | '.join(str(v).replace('|', '\\|').replace('\n', ' ') for v in values) + ' |')
    return '\n'.join(lines) + '\n'


if __name__ == "__main__":
    main()
